import sweep
HERE=Path(__file__).resolve().parent
OUT=HERE/'results'
METHODS=('V4b','V4b-noOpt','Proposed+V1','C1+V1')


def fs_retry(fn):
    for i in range(500):
        try:
            return fn()
        except PermissionError:
            if i == 499:
                raise
            time.sleep(.02)

class FilePool:
    """Persistent Python processes using file IPC (sandbox denies Windows pipes).

    Independent episodes run in processes; threads only wait for file replies.
    IPC and error files live in a temporary directory and are not artifacts.
    """
    def __init__(self, workers, initializer=None):
        self.workers = workers

    def __enter__(self):
        self.tmp = tempfile.TemporaryDirectory(prefix='v4_ipc_')
        self.slots = queue.Queue(); self.processes = []; self.errors = []
        self.threads = ThreadPoolExecutor(self.workers)
        for i in range(self.workers):
            d = Path(self.tmp.name)/str(i); d.mkdir()
            err = (d/'stderr.txt').open('w',encoding='utf-8'); self.errors.append(err)
            proc = subprocess.Popen([sys.executable,'-X','utf8',str(Path(__file__).resolve()),'--worker-dir',str(d)],
                                    stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=err,
                                    creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
            self.processes.append(proc); self.slots.put((d,proc))
        return self

    def call(self, job):
        d,proc = self.slots.get()
        try:
            tmp=d/'request.tmp'
            tmp.write_text(json.dumps(job,default=lambda x:x.tolist()),encoding='utf-8')
            fs_retry(lambda:tmp.replace(d/'request.json'))
            while not (d/'response.json').exists():
                if proc.poll() is not None:
                    raise RuntimeError((d/'stderr.txt').read_text(encoding='utf-8'))
                time.sleep(.03)
            reply=json.loads(fs_retry(lambda:(d/'response.json').read_text(encoding='utf-8')))
            fs_retry(lambda:(d/'response.json').unlink())
            if 'error' in reply:
                raise RuntimeError(reply['error'])
            return reply['row']
        finally:
            self.slots.put((d,proc))

    def map(self, fn, jobs, chunksize=1):
        return list(self.threads.map(self.call,jobs))

    def imap_unordered(self, fn, jobs, chunksize=1):
        futures=[self.threads.submit(self.call,j) for j in jobs]
        for f in as_completed(futures):
            yield f.result()

    def __exit__(self, *exc):
        self.threads.shutdown(wait=True)
        for d in Path(self.tmp.name).iterdir():
            (d/'stop').touch()
        for p in self.processes:
            p.wait()
        for f in self.errors:
            f.close()
        self.tmp.cleanup()

def worker_loop(d):
    d=Path(d)
    warmup()
    while not (d/'stop').exists():
        req=d/'request.json'
        if not req.exists():
            time.sleep(.03); continue
        try:
            job=json.loads(fs_retry(lambda:req.read_text(encoding='utf-8')))
            fs_retry(lambda:req.unlink())
            reply=dict(row=episode(job))
        except Exception:
            reply=dict(error=traceback.format_exc())
        tmp=d/'response.tmp'
        tmp.write_text(json.dumps(reply,allow_nan=False),encoding='utf-8')
        fs_retry(lambda:tmp.replace(d/'response.json'))

def save(name, data):
    OUT.mkdir(exist_ok=True)
    target = OUT/name
    tmp = target.with_suffix('.tmp')
    tmp.write_text(json.dumps(data, ensure_ascii=False, indent=1, allow_nan=False), encoding='utf-8')
    tmp.replace(target)

def train_scenes():
    out = []
    for fi, fam in enumerate(CE.FAMS):
        rng = np.random.default_rng(190000+1000*fi)
        for i in range(10):
            p, T = SV.make(fam, rng)
            out.append((fam, 190000+1000*fi+i, p, T))
    return out

def eval_scenes():
    out = [('diag', fam, sid, p, T) for fam, sid, p, T in CE.cohort('diag', 50)]
    out += [('sweep', f'{kind}:{dose:g}', sid, p, T) for kind, dose, sid, p, T in sweep.scenes()]
    assert all(not 130000 <= s[2] < 140000 for s in out)
    return out

def summary(rows):
    finite = [r['rmse'] for r in rows if r['rmse'] is not None]
    return dict(n=len(rows), rmse_median=float(np.median(finite)) if finite else None,
                rmse_mean=float(np.mean(finite)) if finite else None,
                runaway=sum(r['runaway'] for r in rows), diverged=sum(r['diverged'] for r in rows),
                long_loss=sum(r['long_loss'] is True for r in rows), loss_unknown=sum(r['long_loss'] is None for r in rows))


def build(name, params=None):
    if name=='V4b': return V4b(**(params or {}))
    if name=='V4b-noOpt': return V4bNoOpt(**(params or {}))
    if name=='Proposed+V1': return ServoID(single_model=False, **CE.FINAL)
    if name=='C1+V1': return V4(motion=False, ru=0.)
    raise ValueError(name)


def episode(job, keep_times=False):
    idx,name,params,scene=job
    split,fam,sid,p,T=scene
    assert not 130000<=sid<140000
    pol=build(name,params)
    log=P.episode(p,pol,T=T,seed=sid)
    m=common.task_metrics(log,20.8)
    finite=not m['diverged'] and np.isfinite(m['rmse'])
    row=dict(index=idx,method=name,split=split,family=fam,seed=sid,
             rmse=float(m['rmse']) if finite else None,
             peak=float(m['peak']) if finite else None,
             runaway=bool(not finite or m['peak']>50),diverged=not finite,
             long_loss=bool(m['loss_max']>.5) if finite else None,
             loss_max=float(m['loss_max']) if finite else None,
             L=math.log1p(min(float(m['J']),1000)) if finite else math.log1p(1000))
    if isinstance(pol,V4b):
        row['diagnostic']=dict(pol.counts,first_motion_s=pol.first_motion_time,
             max_ff_increment_m=pol.max_ff_increment,sum_abs_ff_m=pol.sum_ff_abs,
             sum_rebase_abs_m=pol.sum_rebase_abs,max_command_identity_error_m=pol.max_command_identity_error,
             mean_abs_opt_reference_m=pol.sum_opt_abs/max(pol.counts['ticks'],1),
             max_residual_velocity_mps=pol.max_residual_velocity,
             tau_hat=pol.c1.tau_hat,ndel_hat=pol.c1.ndel_hat)
    if keep_times: return row,pol.t_call
    return row


def warmup():
    fam,sid,p,T=train_scenes()[0]
    for name in METHODS: episode((0,name,{},('warm',fam,sid,p,1.3)))


def check():
    from v4b_architecture import ResidualC1
    from contact_update import ContactUpdate
    from candidate1_model import _sync
    fam,sid,p,T=train_scenes()[0]
    # Separate executor with no FF and no ID must reproduce fresh-force
    # C1 gains on the same direct-interface history, including internal states.
    class Exact(V4b):
        def reset(self, pl):
            super().reset(pl)
            self.reference=ContactUpdate(k0=3e4); self.reference.reset(pl)
            self.max_state_error=0.
        def __call__(self,o):
            k=o.n-1
            if k:
                # Reference consumes completed direct rows, independently.
                pass
            g=self.reference(P.Obs(o.log,k))
            cmd=super().__call__(o)
            np.testing.assert_allclose(self.c1.g,g,atol=1e-13,rtol=1e-13)
            if k:
                np.testing.assert_allclose(self.c1.rs,self.reference.rs,atol=1e-13,rtol=1e-13)
            return cmd
    P.episode(p,Exact(motion=False),T=.45,seed=sid)
    # FF coordinate identity: F=k*(y+s)=k*((y-yff)+(s+yff)).
    r=np.random.default_rng(82); y,s,yff=r.normal(size=(3,100))
    np.testing.assert_allclose(7000*(y+s),7000*((y-yff)+(s+yff)),atol=1e-10)
    # FINAL increment path, including startup anchor, vs the actual base step
    # on an identical physical history: isolate its feedback/excitation terms.
    pol=V4b(); P.episode(p,pol,T=1.5,seed=sid)
    assert pol.counts['motion_ticks']>0, 'startup observer never ready'
    assert pol.max_command_identity_error < 1e-12
    no=V4bNoOpt(); P.episode(p,no,T=1.5,seed=sid)
    D,KP=no.c1.rule(no.c1.kuse)
    if not no.c1.mode:
        np.testing.assert_allclose(no.c1.g[1],D)
        np.testing.assert_allclose(no.c1.g[4],KP)
        np.testing.assert_allclose(no.c1.x[2:],0.)
    import candidate1_model as C
    import v4b_kernels as K
    c=ContactUpdate(); c.reset(P.PLATFORMS['PC125'])
    x=np.array([math.log(200.),1.,.2,-.1])
    st=np.array([.001,.001,.2,.001,.001,4.,.001,4.,7000.,.002,.03,.001,0.,0.,0.,0.])
    q=np.array([.001]); dith=np.zeros(c.H)
    r0=np.zeros(c.nr);r1=np.zeros(c.nr)
    C._resid(x,c.H,c.per,st,q,dith,c.pr,c.scen,x,x,c.rw,r0)
    K._resid(x,c.H,c.per,st,q,dith,c.pr,c.scen,x,x,c.rw,r1)
    np.testing.assert_allclose(r0,r1,rtol=0,atol=0)
    # FF is already in the residual drift r=s+a_ff. Without saturation,
    # including known FF in physical allocation and returning to residual
    # coordinates must leave the residual-force rollout unchanged.
    a=np.zeros(3*c.H+1);b=a.copy();shift=.00012
    pr_free=c.pr.copy();pr_free[4]=1000.
    K._roll(x,c.H,c.per,np.r_[st,shift],q,dith,pr_free,1.,0.,1.,a,0,0,0.)
    K._roll(x,c.H,c.per,np.r_[st,0.],q,dith,pr_free,1.,0.,1.,b,0,0,0.)
    np.testing.assert_allclose(a,b,rtol=1e-10,atol=1e-10)
    # If the physical command slew is zero, an arbitrary nominal u0 cannot
    # move the predicted contact. This specifically tests the final cap.
    pr=c.pr.copy();pr[4]=0.
    xx=x.copy();xx[2]=15.
    K._roll(x,c.H,c.per,np.r_[st,0.],q,dith,pr,1.,0.,1.,a,0,0,0.)
    K._roll(xx,c.H,c.per,np.r_[st,0.],q,dith,pr,1.,0.,1.,b,0,0,0.)
    np.testing.assert_allclose(a,b,rtol=0,atol=0)
    save('v4b_checks.json',dict(passed=True,noFF_gain_and_state_equivalence=True,
         residual_coordinate_identity=True,legacy_16state_residual_exact=True,known_current_FF_allocation=True,no_double_counted_FF_force=True,nominal_command_slew_cap=True,startup_motion_ticks=pol.counts['motion_ticks'],
         true_prior_noOpt=True,iters=pol.c1.iters,H=pol.c1.H))
    print('CHECK PASSED',flush=True)


def evaluate(workers):
    path=OUT/'v4b_episode_summary.json'
    rows=json.loads(path.read_text(encoding='utf-8')) if path.exists() else []
    done={(r['method'],r['split'],r['family'],r['seed']) for r in rows}
    sc=eval_scenes()
    jobs=[(i,n,{},s) for i,n in enumerate(METHODS) for s in sc if (n,s[0],s[1],s[2]) not in done]
    with FilePool(workers) as pool:
        for i,row in enumerate(pool.imap_unordered(episode,jobs)):
            rows.append(row)
            if (i+1)%50==0:
                save('v4b_episode_summary.json',rows)
                print(f'EVAL {len(rows)}/{len(METHODS)*len(sc)}',flush=True)
    save('v4b_episode_summary.json',sorted(rows,key=lambda r:(r['split'],r['family'],r['seed'],r['method'])))


def timing():
    warmup()
    out={}
    sc=[s for s in eval_scenes() if s[0]=='diag' and s[2]%1000==0]
    for name in METHODS:
        times=[]
        for scene in sc:
            _,tt=episode((0,name,{},scene),True); times.extend(tt[1:])
        out[name]=dict(p50_ms=float(np.percentile(times,50)*1000),
                       p99_ms=float(np.percentile(times,99)*1000),ticks=len(times))
        print('TIMING',name,out[name],flush=True)
    save('v4b_timing.json',dict(methods=out,protocol='Single process, five fixed diagnostic scenes; excludes first tick, JIT, plant and communication; includes estimator, IMM, ID, GN, coordinate transform and diagnostics.',cpu=platform.processor(),python=platform.python_version()))


def bootstrap(rows,ref,method='V4b'):
    a={r['seed']:r for r in rows if r['method']==method}
    b={r['seed']:r for r in rows if r['method']==ref}
    d=np.array([a[s]['rmse']-b[s]['rmse'] for s in sorted(a.keys()&b.keys()) if a[s]['rmse'] is not None and b[s]['rmse'] is not None])
    if not len(d): return dict(n_pairs=0,excluded_pairs=len(a),mean_difference=None,ci95=None)
    rng=np.random.default_rng(20261101)
    means=np.mean(d[rng.integers(0,len(d),size=(4000,len(d)))],axis=1)
    return dict(n_pairs=len(d),excluded_pairs=len(a)-len(d),mean_difference=float(d.mean()),ci95=np.percentile(means,[2.5,97.5]).tolist(),resamples=4000)



def tune(workers):
    # No new coupling scalar: future FF increments are exactly held at zero.
    # One configuration, no artificial duplicate trials; same <=61 allowance.
    sc=[('tune',f,sid,p,T) for f,sid,p,T in train_scenes()]
    result={}
    with FilePool(workers) as pool:
        for name in METHODS:
            rows=pool.map(episode,[(0,name,{},scene) for scene in sc])
            fam={f:float(np.mean([r['L'] for r in rows if r['family']==f])) for f in CE.FAMS}
            result[name]=dict(params={},objective=float(np.mean(list(fam.values()))),family_L=fam,
                             rows=rows,unique_trials=1,budget=61)
            print('TUNE',name,result[name]['objective'],flush=True)
    save('v4b_tuning.json',dict(methods=result,protocol='No new free coupling parameter: future FF increments held at zero. Existing C1 and FINAL parameters frozen. Each method uses one unique candidate under the same maximum allowance of 61; duplicate evaluations do not constitute tuning. Seeds190000+, ten/family. Equal-family mean log(1+min(J,1000)), same as tune_v2.'))


